#include "audio/MaterialFoleyRuntime.hpp"
#include "core/Saturating.hpp"
#include <algorithm>
#include <cmath>
namespace elysium::audio {namespace{std::uint64_t mix(std::uint64_t x){x+=0x9e3779b97f4a7c15ULL;x=(x^(x>>30))*0xbf58476d1ce4e5b9ULL;x=(x^(x>>27))*0x94d049bb133111ebULL;return x^(x>>31);}double unit(std::uint64_t x){return double(x>>11)*(1.0/9007199254740992.0);}}
bool MaterialFoleyRuntime::publish(MaterialAudioFamily f){if(!f.contentId||!f.materialClassId||f.sets.empty())return false;for(auto&s:f.sets){if(s.variations.empty())return false;for(auto&v:s.variations)if(!v.assetContentId||!std::isfinite(v.minPitch)||!std::isfinite(v.maxPitch)||v.minPitch<0||v.maxPitch<v.minPitch)return false;}familiesByMaterial_[f.materialClassId]=std::move(f);return true;}void MaterialFoleyRuntime::setFallback(std::uint64_t id){fallbackMaterial_=id;}
AudioEventPacket MaterialFoleyRuntime::resolve(const FoleyRequest&r,const AudioVoiceBudget&b)const{AudioEventPacket o;o.eventStableId=r.eventStableId;o.actorStableId=r.actorStableId;if(!r.eventStableId||!r.materialClassId||b.maxConcurrent==0||b.currentlyActive>=b.maxConcurrent)return o;auto fi=familiesByMaterial_.find(r.materialClassId);bool fallback=false;if(fi==familiesByMaterial_.end()&&fallbackMaterial_){fi=familiesByMaterial_.find(fallbackMaterial_);fallback=true;}if(fi==familiesByMaterial_.end())return o;auto si=std::find_if(fi->second.sets.begin(),fi->second.sets.end(),[&](auto&s){return s.kind==r.kind;});if(si==fi->second.sets.end())return o;auto choices=si->variations;std::sort(choices.begin(),choices.end(),[](auto&a,auto&b){return a.assetContentId<b.assetContentId;});auto h=mix(r.eventStableId^mix(r.materialClassId)^mix(static_cast<std::uint64_t>(r.kind)));std::size_t idx=static_cast<std::size_t>(h%choices.size());if(choices.size()>1&&choices[idx].assetContentId==r.previousAssetId)idx=(idx+1)%choices.size();auto&v=choices[idx];o.assetContentId=v.assetContentId;o.pitch=v.minPitch+(v.maxPitch-v.minPitch)*unit(mix(h));o.intensity=elysium::safe::finiteClamp(r.intensity,v.minIntensity,v.maxIntensity);o.fallback=fallback;o.voiceGroupId=fi->second.contentId;return o;}
} // namespace elysium::audio
